mapper.update:
UPDATE members
SET region_verified_at = UTC_TIMESTAMP()
WHERE member_id = #{memberId}
    AND region_id = #{regionId}
    AND account_status = 'ACTIVE'
    AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM members
WHERE nickname = #{nickname}
AND member_id <> #{memberId}

mapper.update:
UPDATE members
SET nickname = #{nickname}
WHERE member_id = #{memberId}
AND deleted_at IS NULL

UPDATE members
SET profile_img_url = #{profileImageUrl, jdbcType=VARCHAR}
WHERE member_id = #{memberId}
    AND deleted_at IS NULL

