mapper.update:
UPDATE members
SET password_hash = #{passwordHash}
WHERE member_id = #{memberId}
    AND account_status = 'ACTIVE'
    AND deleted_at IS NULL

UPDATE members
SET password_hash = #{newPasswordHash}
WHERE member_id = #{memberId}
    AND BINARY password_hash = BINARY #{currentPasswordHash}
    AND account_status = 'ACTIVE'
    AND deleted_at IS NULL
